<?= $this->extend('admin/layout') ?><?= $this->section('content') ?><p><a class="button" href="<?= site_url('admin/students/new') ?>">Add student</a></p><form class="filters" method="get"><label>Search<input name="q" value="<?= esc($q,'attr') ?>" placeholder="ID, name, email, program, department"></label><label>Status<select name="status"><option value="">All</option><option value="enrolled" <?= $status==='enrolled'?'selected':'' ?>>Enrolled</option><option value="not_enrolled" <?= $status==='not_enrolled'?'selected':'' ?>>Not enrolled</option></select></label><button>Filter</button><?php if($q!==''||$status!==''): ?><a class="button" href="<?= site_url('admin/students') ?>">Clear filters</a><?php endif ?></form><div class="table-wrap"><table><thead><tr><th>Student ID</th><th>Name</th><th>Email</th><th>Program</th><th>Status</th></tr></thead><tbody><?php foreach($students as $s):?><tr class="row-link" data-row-link="<?= esc(site_url('admin/students/'.$s['id']),'attr') ?>" tabindex="0" aria-label="Open student <?= esc($s['student_id'],'attr') ?>"><td><a href="<?= site_url('admin/students/'.$s['id']) ?>"><?= esc($s['student_id']) ?></a></td><td><?= esc($s['full_name']) ?></td><td><?= esc($s['institutional_email']) ?></td><td><?= esc($s['program']) ?></td><td><span class="status-badge <?= esc($s['enrollment_status'],'attr') ?>"><?= esc(ucwords(str_replace('_',' ',$s['enrollment_status']))) ?></span></td></tr><?php endforeach ?><?php if (!$students): ?><tr><td colspan="5">No students match these filters.</td></tr><?php endif ?></tbody></table></div><?= $pager->links() ?><?= $this->endSection() ?>
